changeList.full_content:
import {validatePersonalVatNumbers} from './vat-field';

describe(`test validatePersonalVatNumbers right`, function () {
  it(`should pass right props`, function () {
    // @ts-expect-error just testing wrong inputs
    expect(validatePersonalVatNumbers()).toBe(false);
  });

  it(`should return false for empty vatNumber`, function () {
    expect(validatePersonalVatNumbers(`de-DE`, ``)).toBe(false);
  });

  // de-DE right formats
  it(`should return true for valid de-DE vatNumber`, function () {
    expect(validatePersonalVatNumbers(`de-DE`, `DE123456789`)).toBe(true);
    expect(validatePersonalVatNumbers(`de-DE`, `de123456789`)).toBe(false);
    expect(validatePersonalVatNumbers(`de-DE`, `1`.repeat(11))).toBe(true);
    expect(validatePersonalVatNumbers(`de-DE`, `1`.repeat(13))).toBe(true);
  });

  // pt-PT right formats
  it(`should return true for valid pt-PT vatNumber`, function () {
    expect(validatePersonalVatNumbers(`pt-PT`, `PT123456789`)).toBe(true);
    expect(validatePersonalVatNumbers(`pt-PT`, `123456789`)).toBe(true);
  });

  // de-AT right formats
  it(`should return true for valid de-AT vatNumber`, function () {
    expect(validatePersonalVatNumbers(`de-AT`, `ATU12345678`)).toBe(true);
    expect(validatePersonalVatNumbers(`de-AT`, `1`.repeat(11))).toBe(true);
    expect(validatePersonalVatNumbers(`de-AT`, `1`.repeat(13))).toBe(true);
  });

  // nl-BE \ fr-BE  right formats
  it(`should return true for valid nl-BE / fr-BE vatNumber`, function () {
    expect(validatePersonalVatNumbers(`nl-BE`, `BE1234567890`)).toBe(true);
    expect(validatePersonalVatNumbers(`fr-BE`, `BE1234567890`)).toBe(true);
  });

  // de-CH
  it(`should return true for valid de-CH vatNumber`, function () {
    expect(validatePersonalVatNumbers(`de-CH`, `123456`)).toBe(true);
    expect(validatePersonalVatNumbers(`de-CH`, `CHE123456789`)).toBe(true);
  });

  // it-CH \ fr-CH right formats
  it(`should return true for valid it-CH / fr-CH vatNumber`, function () {
    expect(validatePersonalVatNumbers(`it-CH`, `CHE123456789`)).toBe(true);
    expect(validatePersonalVatNumbers(`fr-CH`, `CHE123456789`)).toBe(true);
  });

  // it-IT right formats
  it(`should return true for valid it-IT vatNumber`, function () {
    expect(validatePersonalVatNumbers(`it-IT`, `1`.repeat(11))).toBe(true);
    expect(validatePersonalVatNumbers(`it-IT`, `1`.repeat(12))).toBe(false);
  });

  // fr-FR right formats
  it(`should return true for valid fr-FR vatNumber`, function () {
    expect(validatePersonalVatNumbers(`fr-FR`, `FR12345678901`)).toBe(true);
  });

  // nl-NL right formats
  it(`should return true for valid nl-NL vatNumber`, function () {
    expect(validatePersonalVatNumbers(`nl-NL`, `NL123456789012`)).toBe(true);
  });

  // sv-SE right formats
  it(`should return true for valid sv-SE vatNumber`, function () {
    expect(validatePersonalVatNumbers(`sv-SE`, `SE123456789001`)).toBe(true);
  });

  // en-GB right formats
  it(`should return false for other country vatNumber`, function () {
    expect(validatePersonalVatNumbers(`en-GB`, `GB123456789`)).toBe(true);
    expect(validatePersonalVatNumbers(`en-GB`, `1`.repeat(10))).toBe(true);
  });
});

